 void sheet(){if(a.pickedCover.isEmpty()&&coverFile().exists())try{a.pickedCover=android.util.Base64.encodeToString(java.nio.file.Files.readAllBytes(coverFile().toPath()),2);}catch(Exception ignored){}page(0,"Prepare sua história");a.coverPreview=new ImageView(a);a.coverPreview.setScaleType(ImageView.ScaleType.CENTER_CROP);a.coverPreview.setBackground(a.outline(CARD,14));a.body.addView(a.coverPreview,new LinearLayout.LayoutParams(-1,a.dp(190)));if(!a.pickedCover.isEmpty())try{byte[] b=android.util.Base64.decode(a.pickedCover,2);a.coverPreview.setImageBitmap(BitmapFactory.decodeByteArray(b,0,b.length));}catch(Exception ignored){}else if(!draft.optString("cover_url").isEmpty())a.image(a.coverPreview,draft.optString("cover_url"));a.button(a.body,"Escolher capa",CARD,()->a.pick(8,"image/*"));EditText title=a.field(a.body,"TÍTULO","Nome da série ou novela",false),description=a.field(a.body,"DESCRIÇÃO","Conte ao público sobre sua história",false);title.setFilters(new InputFilter[]{new InputFilter.LengthFilter(100)});description.setSingleLine(false);description.setMinLines(4);description.setFilters(new InputFilter[]{new InputFilter.LengthFilter(3000)});title.setText(draft.optString("title"));description.setText(draft.optString("synopsis"));watch(title,"title");watch(description,"synopsis");Spinner format=a.select(a.body,"TIPO DE PRODUÇÃO",new String[]{"Série","Novela","Minissérie","Drama"},formatName(draft.optString("format"))),genre=a.select(a.body,"GÊNERO",new String[]{"Drama","Romance","Suspense","Ação","Comédia","Novela"},draft.optString("genre","Drama")),rating=a.select(a.body,"CLASSIFICAÇÃO",new String[]{"Livre","10","12","14","16","18"},draft.optString("rating","Livre"));format.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int pos,long id){put("format",new String[]{"series","novela","mini","drama"}[pos]);}});a.text(a.body,"Sua ficha é salva neste aparelho. A capa será enviada ao tocar em Próximo.",12,MUTED);a.button(a.body,"Próximo · enviar capítulos",RED,()->a.safe(()->{put("genre",genre.getSelectedItem().toString());put("rating",rating.getSelectedItem().toString());if(title.getText().toString().trim().isEmpty()||description.getText().toString().trim().isEmpty()){a.notice("Preencha título e descrição.",true);return;}if(a.pickedCover.isEmpty()&&draft.optString("cover_path").isEmpty()){a.notice("Escolha a capa da produção.",true);return;}JSONObject payload=a.obj("draft_id",draftId,"title",title.getText().toString(),"synopsis",description.getText().toString(),"format",new String[]{"series","novela","mini","drama"}[format.getSelectedItemPosition()],"genre",genre.getSelectedItem().toString(),"rating",rating.getSelectedItem().toString());if(draft.optInt("id")>0)payload.put("id",draft.optInt("id"));if(!a.pickedCover.isEmpty())payload.put("cover",a.pickedCover);post("/save",payload,r->{current=r;draft=new JSONObject(r.toString());draft.put("draft_id",draftId);a.pickedCover="";coverFile().delete();remember();chapters(0);});}));}
